"""Sudoku board logic: generation, validation and completion checks."""

import random


class SudokuBoard:
    SIZE = 9

    def __init__(self, holes=40, seed=None):
        self.grid = [[0] * self.SIZE for _ in range(self.SIZE)]
        self.fixed = [[False] * self.SIZE for _ in range(self.SIZE)]
        if seed is not None:
            random.seed(seed)
        self._generate(holes)

    # ---------- generation ----------
    def _generate(self, holes):
        self._fill(0)
        cells = [(r, c) for r in range(self.SIZE) for c in range(self.SIZE)]
        random.shuffle(cells)
        removed = 0
        for r, c in cells:
            if removed >= holes:
                break
            backup = self.grid[r][c]
            self.grid[r][c] = 0
            if self._count_solutions() != 1:
                self.grid[r][c] = backup
            else:
                removed += 1
        for r in range(self.SIZE):
            for c in range(self.SIZE):
                self.fixed[r][c] = self.grid[r][c] != 0

    def _fill(self, idx):
        if idx == self.SIZE * self.SIZE:
            return True
        r, c = divmod(idx, self.SIZE)
        digits = list(range(1, 10))
        random.shuffle(digits)
        for n in digits:
            if self._valid(r, c, n):
                self.grid[r][c] = n
                if self._fill(idx + 1):
                    return True
                self.grid[r][c] = 0
        return False

    def _count_solutions(self, cap=2):
        for idx in range(self.SIZE * self.SIZE):
            r, c = divmod(idx, self.SIZE)
            if self.grid[r][c] == 0:
                total = 0
                for n in range(1, 10):
                    if self._valid(r, c, n):
                        self.grid[r][c] = n
                        total += self._count_solutions(cap)
                        self.grid[r][c] = 0
                        if total >= cap:
                            break
                return total
        return 1

    # ---------- rules ----------
    def _valid(self, r, c, n):
        if any(self.grid[r][j] == n for j in range(self.SIZE) if j != c):
            return False
        if any(self.grid[i][c] == n for i in range(self.SIZE) if i != r):
            return False
        br, bc = 3 * (r // 3), 3 * (c // 3)
        for i in range(br, br + 3):
            for j in range(bc, bc + 3):
                if (i, j) != (r, c) and self.grid[i][j] == n:
                    return False
        return True

    def conflicts(self, r, c):
        """True if the value at (r, c) breaks a row/column/box rule."""
        n = self.grid[r][c]
        return n != 0 and not self._valid(r, c, n)

    def find_mistakes(self):
        return [(r, c) for r in range(self.SIZE) for c in range(self.SIZE)
                if self.conflicts(r, c)]

    def is_complete(self):
        return (all(self.grid[r][c] != 0
                    for r in range(self.SIZE) for c in range(self.SIZE))
                and not self.find_mistakes())

    # ---------- play ----------
    def place(self, r, c, value):
        """Set cell (r, c) to value (1-9) or clear it with 0."""
        if not (0 <= r < self.SIZE and 0 <= c < self.SIZE):
            return False, "Row and column must be between 1 and 9."
        if self.fixed[r][c]:
            return False, "That cell is a given clue and cannot be changed."
        if not (0 <= value <= 9):
            return False, "Value must be 0-9 (0 clears the cell)."
        self.grid[r][c] = value
