"""Classic 9x9 Sudoku - console edition. Run: python main.py"""

from sudoku import SudokuBoard

PROMPTS = (
    "Row (1-9, 'q' to quit): ",
    "Column (1-9, 'q' to quit): ",
    "Value (1-9, 0 to clear, 'q' to quit): ",
)


def read_number(prompt, low, high):
    """Read an integer in [low, high]; return None if the player quits."""
    while True:
        text = input(prompt).strip().lower()
        if text in ("q", "quit", "exit"):
            return None
        try:
            value = int(text)
        except ValueError:
            value = None
        if value is not None and low <= value <= high:
            return value
        print(f"  Please enter a whole number from {low} to {high}.")


def main():
    print("=" * 40)
    print("        CLASSIC SUDOKU (9 x 9)")
    print("=" * 40)
    print("Fill every row, column and 3x3 box with the")
